    parent = list(range(n + 1))  # 1-based indexing
    rank = [1] * (n + 1)

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])  # Path compression
        return parent[u]

    total_weight = 0
    count = 0  # Number of edges added to MST

    for u, v, w in edges:
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
