from collections import deque

def determine_capital(N: int, M: int, A: int, B: int, residents: list[int], roads: list[tuple[int, int]]) -> int:
    # Build the adjacency list
    adj = [[] for _ in range(N + 1)]  # Cities are 1-based
    for u, v in roads:
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        dist = [float('inf')] * (N + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] > dist[u] + 1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    # Calculate for city A
    dist_A = bfs(A)
    sum_A = 0
    for i in range(1, N + 1):
        sum_A += dist_A[i] * residents[i - 1]  # residents are 0-based

    # Calculate for city B
    dist_B = bfs(B)
    sum_B = 0
    for i in range(1, N + 1):
        sum_B += dist_B[i] * residents[i - 1]

    # Compare the sums
    if sum_A < sum_B:
        return A
    elif sum_B < sum_A:
        return B
    else:
        return min(A, B)

