def minimize_largest_sum(n: int, k: int, a: List[int]) -> int:
    total = sum(a)
    max_element = max(a)
    low = max_element
    high = total
    while low < high:
        mid = (low + high) // 2
        current_sum = 0
        count = 1
        for num in a:
            current_sum += num
            if current_sum > mid:
                count += 1
                current_sum = num
                if count > k:
